typeDefinitions.declaration:
export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface MultiSelectProps extends Omit<SelectHTMLAttributes<HTMLSelectElement>, "multiple" | "value" | "defaultValue" | "onChange"> {
  options: SelectOption[];
  value?: string[];
  defaultValue?: string[];
  onChange?: (values: string[]) => void;
  /** Use dropdown for ordinary collection choices. Native remains the compatibility default. */
  presentation?: "native" | "dropdown" | "checkboxes";
  /** Localized collapsed text when a dropdown has no selected values. */
  emptySelectionLabel?: string;
  /** Required when using the checkbox presentation; describes its clear action. */
  clearSelectionLabel?: string;
  disabledReason?: string;
}

example.usage:
import { MultiSelect, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

// Before using this template, inspect the target project's existing form-column
// token, layout rule or container. Bind its class below and record its source in
// declaration.fieldColumns. Do not copy the documentation-only 28rem context.
// If no host rule exists, stop for the host layout decision; never invent a DS token.
export function Example({ formColumnClassName }: { formColumnClassName: string }) {
  if (!formColumnClassName) throw new Error("HOST_FORM_COLUMN_DECISION_REQUIRED");
  const options = [{ value: "review", label: "Review" }, { value: "release", label: "Release" }];
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" className={formColumnClassName} data-tcrn-field-column="" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <MultiSelect aria-label="Projects" options={options} presentation="dropdown" emptySelectionLabel="Choose"/>
    </div>
  </>;
}
